export interface ImportResult { profile: Profile; evaluation: any }

export class AgentCatalog {
  db: CatalogDB;
  registry: ActivationRegistry;
  constructor(dbPath = ':memory:') { this.db = new CatalogDB(dbPath); this.registry = new ActivationRegistry(this.db); }
  close() { this.db.close(); }

  importText(text: string, opts: { sourceRepo: string; sourcePath: string }): ImportResult {
    return this.db.transaction(() => {
    const parsed = parseAgentMarkdown(text, opts);
    const profile = normalizeAgent(parsed);
    const existing = this.db.listProfiles();
    const previous = this.db.getEvaluation(profile.id);
    this.db.upsertProfile(profile);
    const evaluation = runStaticGate(profile, existing);
    if (previous?.version_hash === profile.version_hash && previous.flags.some((flag: string) => flag.startsWith('manual-evaluation:'))) {
      // Import refreshes static evidence, not the human decision. Preserve its
      // original verdict even if a new static failure tightens effective status.
      const manualFlags = (previous.flags as string[]).filter(flag => flag.startsWith('manual-evaluation:'));
      const recordedVerdict = (previous.flags as string[]).find(flag => /^manual-verdict:(passed|pending|rejected)$/.test(flag))?.slice('manual-verdict:'.length);
      const manualVerdict = recordedVerdict || previous.status;
      evaluation.status = evaluation.status === 'rejected' ? 'rejected' : manualVerdict;
      if (typeof previous.score === 'number') evaluation.score = previous.score;
      evaluation.flags = [...new Set([...evaluation.flags, ...manualFlags, `manual-verdict:${manualVerdict}`])];
      const riskOrder = ['low', 'medium', 'high', 'critical'];
      if (riskOrder.indexOf(previous.risk_level) > riskOrder.indexOf(evaluation.risk_level)) evaluation.risk_level = previous.risk_level;
    }
    this.db.setEvaluation(evaluation, profile.version_hash);
    profile.risk_profile = { level: evaluation.risk_level, injection_score: evaluation.injection_score, overlap_score: evaluation.overlap_score, flags: evaluation.flags };
    profile.evaluation_status = evaluation.status;
    profile.activation_status = this.registry.status(profile.id).status;
    this.db.upsertProfile(profile);
    this.db.replaceOverlaps(profile.id, evaluation.overlaps);
    this.db.audit(profile.id, 'import', JSON.stringify({ sourcePath: opts.sourcePath, status: evaluation.status }));
    return { profile, evaluation };
    });
  }

  importDir(dir: string, sourceRepo: string): ImportResult[] {
    const results: ImportResult[] = [];
    for (const f of readdirSync(dir)) {
      if (!/\.md$/i.test(f)) continue;
      results.push(this.importText(readFileSync(join(dir, f), 'utf8'), { sourceRepo, sourcePath: f }));
    }
    return results;
  }

  importTree(dir: string, sourceRepo: string, rootDir?: string): ImportResult[] {
    const root = rootDir || dir;
    const NON_DIV = new Set(['examples', 'strategy', 'integrations', 'scripts', '.github', 'node_modules', '.git']);
    const SKIP = /^(readme|contributing|security|license|changelog)/i;
    const files: string[] = [];
    const walk = (d: string) => {
      for (const name of readdirSync(d)) {
        if (name === '.git' || name === 'node_modules') continue;
        const p = join(d, name);
        const st = statSync(p);
        if (st.isDirectory()) { if (NON_DIV.has(name)) continue; walk(p); }
        else if (/\.md$/i.test(name) && !SKIP.test(name)) files.push(p);
      }
    };
    walk(dir);
    const results: ImportResult[] = [];
    for (const abs of files) {
      const rel = relative(root, abs);
      try { results.push(this.importText(readFileSync(abs, 'utf8'), { sourceRepo, sourcePath: rel })); }
      catch (e) { results.push({ profile: { id: rel, name: rel, division: rel.split('/')[0] } as any, evaluation: { status: 'error', flags: [String((e as Error).message)] } }); }
    }
    return results;
  }

  counts() { return this.db.counts(); }
  search(query: string, topK = 20): Profile[] {
    const q = String(query || '').toLowerCase();
    return this.db.listProfiles().filter(p => JSON.stringify(p).toLowerCase().includes(q)).slice(0, topK);
  }
  list(filter?: { division?: string; status?: string }): Profile[] {
    let list = this.db.listProfiles();
    if (filter?.division) list = list.filter(p => p.division === filter.division);
    if (filter?.status) list = list.filter(p => p.evaluation_status === filter.status);
    return list;
  }
}
import type { CatalogDB } from './db';
import { compile, type Target } from './compiler';

export class ActivationRegistry {
  constructor(private db: CatalogDB) {}

  activate(profileId: string, target: Target) {
    return this.db.transaction(() => {
    const profile = this.db.getProfile(profileId);
    if (!profile) throw new Error(`profile not found: ${profileId}`);
    const ev = this.db.getEvaluation(profileId);
    if (!ev) throw new Error('no evaluation record — activation blocked (no-active-without-eval)');
    if (ev.status !== 'passed') throw new Error(`evaluation not passed: ${ev.status}`);
    if (ev.version_hash !== profile.version_hash) throw new Error('evaluation is stale for current profile version');
    if (!target || !['openclaw', 'codex'].includes(target)) throw new Error(`activation target must be openclaw|codex (got ${target})`);
    const artifact = compile(profile, target);
    this.db.setActivation(profileId, 'active', target, JSON.stringify(artifact));
    this.db.audit(profileId, 'activate', JSON.stringify({ target, evaluation: ev.id }));
    return { profileId, status: 'active' as const, target, artifact };
    });
  }

  deactivate(profileId: string) {
    return this.db.transaction(() => {
    const act = this.db.getActivation(profileId);
    if (!act) throw new Error(`no activation for ${profileId}`);
    this.db.setActivation(profileId, 'deactivated', null, null);
    this.db.audit(profileId, 'deactivate', JSON.stringify({ prior: act.status, target: act.target }));
    return { profileId, status: 'deactivated' as const };
    });
  }

  status(profileId: string) {
    const act = this.db.getActivation(profileId);
    return act ? { profileId, status: act.status, target: act.target } : { profileId, status: 'draft' as const };
  }
}
import { createHash } from 'node:crypto';
import { toList, firstParagraph, type ParsedAgent } from './parser';
import type { Profile } from './db';

function firstNonEmpty(...vals: any[]): string {
  for (const v of vals) if (v && String(v).trim()) return String(v).trim();
  return '';
}
function listOrSplit(val: any, text?: string): string[] {
  if (Array.isArray(val)) return val.map(String);
  if (text) return toList(text);
  return [];
}
function divisionFromPath(sourcePath: string): string {
  const parts = String(sourcePath || '').split('/').filter(Boolean);
  return parts[0] || 'unknown';
}
function slug(s: string): string {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

export function hashProfile(profile: Profile): string {
  const stable = JSON.stringify(profile, Object.keys(profile).sort());
  return createHash('sha256').update(stable).digest('hex').slice(0, 16);
}

export function normalizeAgent(parsed: ParsedAgent): Profile {
  const { frontmatter: fm, sections: s, preamble, sourceRepo, sourcePath } = parsed;
  const name = firstNonEmpty(fm.name, fm.title);
  const division = firstNonEmpty(fm.division, divisionFromPath(sourcePath));
  const id = slug(`${division}/${name}`) || `agent/${Math.random().toString(36).slice(2, 8)}`;
  const persona = firstNonEmpty(fm.vibe && `${fm.vibe}`, preamble && firstParagraph(preamble), s.memory_policy && firstParagraph(s.memory_policy), fm.description);

  const profile: Profile = {
    id, name, division,
    description: firstNonEmpty(fm.description, ''),
    source_repo: sourceRepo || '', source_path: sourcePath || '',
    version_hash: '',
    persona,
    mission: firstNonEmpty(s.mission && firstParagraph(s.mission), fm.description, ''),
    rules: listOrSplit(fm.rules, s.rules),
    workflows: listOrSplit(fm.workflows, s.workflows),
    deliverables: listOrSplit(fm.deliverables, s.deliverables),
    success_metrics: listOrSplit(fm.success_metrics, s.success_metrics),
    memory_policy: firstNonEmpty(s.memory_policy && firstParagraph(s.memory_policy), ''),
    tools_required: listOrSplit(fm.tools_required, s.tools_required),
    runtime_targets: Array.isArray(fm.runtime_targets) ? fm.runtime_targets.map(String) : [],
    risk_profile: { level: 'low', injection_score: 0, overlap_score: 0, flags: [] },
    evaluation_status: 'pending', activation_status: 'draft',
  };
  profile.version_hash = hashProfile(profile);
  return profile;
}
