import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Profile, Evaluation } from './db';

function loadSchema(): any {
  const candidates = [
    join(__dirname, 'schema/djimit-agent-profile.schema.json'),
    join(__dirname, '../src/schema/djimit-agent-profile.schema.json'),
  ];
  for (const p of candidates) { try { return JSON.parse(readFileSync(p, 'utf8')); } catch { /* try next */ } }
  throw new Error('djimit-agent-profile.schema.json not found');
}
const schema = loadSchema();

const TYPEOF: Record<string, string> = { string: 'string', integer: 'number', number: 'number', array: 'Array', object: 'Object', boolean: 'boolean' };
function typeOf(v: any): string {
  if (Array.isArray(v)) return 'Array';
  if (v === null) return 'null';
  return typeof v === 'object' ? 'Object' : typeof v === 'number' ? 'number' : 'string';
}

export function validateSchema(profile: Profile): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  for (const req of schema.required as string[]) {
    if (profile[req as keyof Profile] === undefined || profile[req as keyof Profile] === null || profile[req as keyof Profile] === '') errors.push(`missing required: ${req}`);
  }
  for (const [k, def] of Object.entries<any>(schema.properties)) {
    const v = (profile as any)[k];
    if (v === undefined) continue;
    const want = TYPEOF[def.type];
    if (want && typeOf(v) !== want) errors.push(`${k}: expected ${def.type}, got ${typeOf(v)}`);
  }
  return { valid: errors.length === 0, errors };
}

const INJECTION_PATTERNS = [
  { re: /ignore\s+(all\s+)?(previous|prior)\s+(instructions|rules|prompts)/i, w: 3, flag: 'instruction-override' },
  { re: /disregard\s+(all|any|the)\s+(previous|prior|above)\s+(instructions|rules)/i, w: 3, flag: 'instruction-override' },
  { re: /\bDAN\b|do anything now/i, w: 3, flag: 'jailbreak' },
  { re: /you are now (a |an )?(jailbreak|unrestricted|root|admin)/i, w: 3, flag: 'jailbreak' },
  { re: /act as[^.\n]{0,80} without (restrictions|limits|rules)/i, w: 3, flag: 'jailbreak' },
  { re: /\b(reveal|expose|show|print)\s+(your|the|this)\s+(system\s+)?prompt\b/i, w: 3, flag: 'prompt-exfil' },
  { re: /exfiltrat(e|ion)/i, w: 3, flag: 'exfiltration' },
  { re: /send\s+(data|secrets?|credentials?|tokens?|keys?|passwords?)\s+to\b/i, w: 3, flag: 'exfiltration' },
  { re: /base64[- ]?decode|eval\s*\(\s*atob/i, w: 2, flag: 'obfuscation' },
  { re: /\brm\s+-rf\s+\/|rm\s+-rf\s+~/i, w: 3, flag: 'destructive-shell' },
  { re: /curl\s+[^|\n]{0,120}\|\s*(sh|bash)|wget\s+[^|\n]{0,120}\|\s*(sh|bash)/i, w: 3, flag: 'remote-code-exec' },
  { re: /chmod\s+-R\s+777|chmod\s+777/i, w: 2, flag: 'unsafe-permission' },
  { re: /disable (safety|guardrails|content policy|alignment)/i, w: 3, flag: 'safety-disable' },
  { re: /do not follow (your|the) (rules|instructions|policy)/i, w: 2, flag: 'rule-bypass' },
  { re: /\b(kill|killall|pkill)\b[^.\n]{0,40}-9/i, w: 1, flag: 'aggressive-kill' },
];

export function scanInjection(text: string): { score: number; flags: string[]; level: string } {
  const hay = text || ''; let score = 0; const flags = new Set<string>();
  for (const p of INJECTION_PATTERNS) if (p.re.test(hay)) { score += p.w; flags.add(p.flag); }
  let level = 'low';
  if (score >= 6) level = 'critical'; else if (score >= 3) level = 'high'; else if (score >= 1) level = 'medium';
  return { score, flags: [...flags], level };
}

function profileText(p: Profile): string {
  return [p.name, p.mission, p.persona, ...(p.rules || []), ...(p.deliverables || [])].join(' ');
}
function shingles(text: string, k = 3): Set<string> {
  const words = String(text || '').toLowerCase().replace(/[^\p{L}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
  const set = new Set<string>();
  for (let i = 0; i + k <= words.length; i++) set.add(words.slice(i, i + k).join(' '));
  return set;
}
function jaccard(a: Set<string>, b: Set<string>): number {
  if (!a.size || !b.size) return 0;
  let inter = 0; for (const t of a) if (b.has(t)) inter++;
  return inter / (a.size + b.size - inter);
}
export function overlapScore(a: Profile, b: Profile): number { return jaccard(shingles(profileText(a)), shingles(profileText(b))); }

export function runStaticGate(profile: Profile, existing: Profile[] = []): Evaluation {
  const schemaRes = validateSchema(profile);
  // Scan additional runtime instructions without changing profile-overlap text.
  const inj = scanInjection([
    profileText(profile), profile.description || '',
    ...(profile.workflows || []), ...(profile.tools_required || []),
    profile.memory_policy || '', ...(profile.success_metrics || []),
  ].join(' '));
  let maxOverlap = 0; let overlapWith: string | null = null; const overlaps: { id: string; score: number }[] = [];
  for (const other of existing) {
    if (other.id === profile.id) continue;
    const s = overlapScore(profile, other);
    if (s > 0.5) overlaps.push({ id: other.id, score: s });
    if (s > maxOverlap) { maxOverlap = s; overlapWith = other.id; }
  }
  const passed = schemaRes.valid && inj.score === 0 && maxOverlap < 0.85;
  const riskLevel = inj.level === 'low' ? (maxOverlap >= 0.6 ? 'medium' : 'low') : inj.level;
  return {
    profile_id: profile.id, schema_valid: schemaRes.valid, schema_errors: schemaRes.errors,
    injection_score: inj.score, injection_flags: inj.flags,
    overlap_score: Math.round(maxOverlap * 1000) / 1000, overlap_with: overlapWith, overlaps,
    risk_level: riskLevel,
    flags: [...inj.flags, ...(maxOverlap >= 0.85 ? ['near-duplicate'] : []), ...(!schemaRes.valid ? ['schema-invalid'] : [])],
    status: passed ? 'passed' : 'rejected',
  };
}
import type { Profile } from './db';

export type Target = 'openclaw' | 'codex' | 'claude-code' | 'cursor' | 'gemini-cli' | 'djimit-native';
export const TARGETS: Target[] = ['openclaw', 'codex', 'claude-code', 'cursor', 'gemini-cli', 'djimit-native'];
export interface CompiledArtifact { target: Target; files: Record<string, string>; stub?: boolean }

function clamp(s?: string): string { return String(s ?? '').trim(); }

export function compile(profile: Profile, target: Target): CompiledArtifact {
  switch (target) {
    case 'openclaw': return compileOpenClaw(profile);
    case 'codex': return compileCodex(profile);
    case 'claude-code': return compileClaudeCode(profile);
    case 'cursor': return compileCursor(profile);
    case 'gemini-cli': return compileGeminiCli(profile);
    case 'djimit-native': return { target, files: { 'djimit-agent.yaml': `id: ${profile.id}\nname: ${profile.name}\ndivision: ${profile.division}\nmission: ${JSON.stringify(profile.mission)}\nruntime_targets: [${profile.runtime_targets.join(', ')}]\n` } };
  }
}

function compileOpenClaw(p: Profile): CompiledArtifact {
  const soul = `# SOUL — ${p.name}\n\n${clamp(p.persona) || 'Persona not specified.'}\n\n## Mission\n${clamp(p.mission)}\n`;
  const agents = [
    `# AGENTS — ${p.name}`, '', `Division: ${p.division}`, `Source: ${p.source_repo}/${p.source_path}`, '',
    '## Mission', clamp(p.mission), '',
    '## Critical Rules', ...(p.rules.length ? p.rules.map(r => `- ${r}`) : ['- (none)']), '',
    '## Workflow', ...(p.workflows.length ? p.workflows.map(w => `- ${w}`) : ['- (none)']), '',
    '## Deliverables', ...(p.deliverables.length ? p.deliverables.map(d => `- ${d}`) : ['- (none)']), '',
    '## Success Metrics', ...(p.success_metrics.length ? p.success_metrics.map(m => `- ${m}`) : ['- (none)']), '',
    '## Memory Policy', clamp(p.memory_policy) || '(default — retain task-relevant context only)', '',
    '## Tools Required', ...(p.tools_required.length ? p.tools_required.map(t => `- ${t}`) : ['- (none)']), '',
  ].join('\n');
  const identity = `# IDENTITY — ${p.name}\n\nid: ${p.id}\nname: ${p.name}\ndivision: ${p.division}\nruntime_targets: ${p.runtime_targets.join(', ') || '(none)'}\n`;
  return { target: 'openclaw', files: { 'SOUL.md': soul, 'AGENTS.md': agents, 'IDENTITY.md': identity } };
}

function compileCodex(p: Profile): CompiledArtifact {
  const instructions = [
    `You are ${p.name} (${p.division}).`,
    clamp(p.persona) && `Persona: ${p.persona}`,
    `Mission: ${clamp(p.mission)}`,
    p.rules.length && `Rules:\n${p.rules.map(r => `- ${r}`).join('\n')}`,
    p.workflows.length && `Workflow:\n${p.workflows.map(w => `- ${w}`).join('\n')}`,
    p.tools_required.length && `Tools: ${p.tools_required.join(', ')}`,
  ].filter(Boolean).join('\n\n');
  return { target: 'codex', files: { 'agent.toml': `[agent]\nname = ${JSON.stringify(p.name)}\nmodel = "gpt-4o"\ninstructions = ${JSON.stringify(instructions)}\n` } };
}

function fileStem(id: string): string { return id.replace(/[^a-zA-Z0-9._-]+/g, '-').replace(/^-+|-+$/g, '') || 'agent'; }
function yamlString(value: string): string { return JSON.stringify(clamp(value)); }
function markdownBody(p: Profile): string {
  return [
    `# ${p.name}`,
    '',
    `## Mission\n${clamp(p.mission) || 'Mission not specified.'}`,
    '',
    `## Persona\n${clamp(p.persona) || 'Persona not specified.'}`,
    '',
    '## Rules', ...(p.rules.length ? p.rules.map(rule => `- ${rule}`) : ['- None specified.']),
    '',
    '## Workflow', ...(p.workflows.length ? p.workflows.map(step => `- ${step}`) : ['- None specified.']),
    '',
    '## Deliverables', ...(p.deliverables.length ? p.deliverables.map(item => `- ${item}`) : ['- None specified.']),
    '',
    '## Success Metrics', ...(p.success_metrics.length ? p.success_metrics.map(metric => `- ${metric}`) : ['- None specified.']),
    '',
    `## Memory Policy\n${clamp(p.memory_policy) || 'Retain task-relevant context only.'}`,
    '',
    '## Tools Required', ...(p.tools_required.length ? p.tools_required.map(tool => `- ${tool}`) : ['- None specified.']),
    '',
  ].join('\n');
}

function compileClaudeCode(p: Profile): CompiledArtifact {
  const description = clamp(p.mission) || `Agent for ${p.division}`;
  const tools = p.tools_required.length ? p.tools_required.join(', ') : 'Read, Edit, Bash';
  const content = [`---`, `name: ${yamlString(p.name)}`, `description: ${yamlString(description)}`, `tools: ${yamlString(tools)}`, `---`, '', markdownBody(p)].join('\n');
  return { target: 'claude-code', files: {[`${fileStem(p.id)}.md`]: content} };
}

function compileCursor(p: Profile): CompiledArtifact {
  const content = [`---`, `description: ${yamlString(clamp(p.mission) || `Agent for ${p.division}`)}`, 'globs: **/*', 'alwaysApply: false', `---`, '', markdownBody(p)].join('\n');
  return { target: 'cursor', files: {[`${fileStem(p.id)}.mdc`]: content} };
}

function compileGeminiCli(p: Profile): CompiledArtifact {
  const content = [`---`, `name: ${yamlString(fileStem(p.id))}`, `description: ${yamlString(clamp(p.mission) || `Agent for ${p.division}`)}`, '---', '', markdownBody(p)].join('\n');
  return { target: 'gemini-cli', files: {'SKILL.md': content} };
}
